@app.post('/api/pay')
def pay(order_id: str, amount: float, card_token: str):
    result = payment_service.process_payment(order_id, amount, card_token)
    send_receipt(order_id, result)
    return result

import stripe
from services.validators import validate_card

class PaymentService:
    def process_payment(self, order_id, amount, card_token):
        if not validate_card(card_token):
            raise ValueError('invalid card')
        charge = stripe.Charge.create(amount=amount, source=card_token)
        return {'order_id': order_id, 'status': 'charged', 'charge_id': charge.id}

